// processSelect processes data for select filtering.
func (ReDurabilityLoss) processSelect(data []byte, isEOF bool, pred func(*ReDurabilityLossBytesResult) bool, emitOut func([]byte)) int {
	processed := 0
	reuseResult := &ReDurabilityLossBytesResult{}

	for {
		result, ok := ReDurabilityLoss{}.FindBytesReuse(data[processed:], reuseResult)
		if !ok {
			if isEOF {
				return len(data)
			}
			return processed
		}

		matchIdx := bytes.Index(data[processed:], result.Match)
		if matchIdx < 0 {
			break
		}

		matchEnd := processed + matchIdx + len(result.Match)

		if pred(result) {
			emitOut(result.Match)
		}

		if len(result.Match) > 0 {
			processed = matchEnd
		} else {
			processed++
		}
	}
	return processed
}

